llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Lurasidone has an absolute oral bioavailability of only 9–19% in humans, providing direct threshold-relevant evidence that a large, lipophilic, extensively metabolized drug can fall below 20%; this supports a low prediction for the query, which also has a large, ionizable structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Praziquantel showed 27.2±5.4% bioavailability in patients with hepatic cirrhosis, a diseased population with reduced first-pass metabolism; this is above the 20% threshold and thus contradicts a low prediction, but the condition limits its relevance to normal absorption.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Solifenacin has an absolute oral bioavailability of 88% in healthy men, demonstrating high F for a lipophilic basic drug; however, it lacks the dual acidic carboxylate/phosphinate groups that dominate the query's permeability profile, so this high-F evidence is not mechanistically transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "SAHA (vorinostat) has 43% oral bioavailability in humans, another high-F example; but it is a neutral hydroxamic acid without the ionized phosphinate that is expected to limit the query's absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is fosinoprilat, a dual-acid phosphinate ACE inhibitor whose ionized carboxylate and phosphinate groups severely limit passive permeability and oral absorption. Lurasidone's low absolute F (9–19%) is the most directly supportive transferable evidence, while high-F records come from non-acidic chemotypes and do not overcome this absorption liability.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for fosinoprilat is present in the provided evidence.",
    "No evidence molecule contains the same dual-acid phosphinate motif, so the permeability penalty of the ionized phosphinate is not directly represented.",
    "High-F analogues are structurally distant and may not capture the absorption barrier created by the query's two acidic groups."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

